constraints:
1 ≤ N ≤ 10^{3}
-10^{9} ≤ arr[i][j] ≤ 10^{9}

expected time complexity: O(N^{2})
expected auxiliary space: O(N)

standard_solution_code:
from math import gcd

class Solution:

	def mostBalloons(self, N, arr):
		if N < 3:
			return N
		ans = 0
		for i in range(N - 1):
			a = arr[i]
			di = {}
			curr = 1
			for j in range(i + 1, N):
				b = arr[j]
				rise = b[1] - a[1]
				run = b[0] - a[0]
				if rise == 0 and run == 0:
					curr += 1
				elif rise == 0 or run == 0:
					if rise:
						s = 10 ** 9 + 1
					else:
						s = 0
					di[s] = di.get(s, 0) + 1
				else:
					s = rise / run
					di[s] = di.get(s, 0) + 1
			for i in di.values():
				ans = max(ans, i + curr)
		return ans
